const ico=(n)=>`<svg class="ico" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.spark}</svg>`; const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); const q=s=>encodeURIComponent(String(s)).replace(/'/g,'%27'); const uq=s=>decodeURIComponent(s); const btn=(label,act,icon='',cls='')=>`<button class="${cls}" data-act="${esc(act)}" aria-label="${esc(label)}">${icon?ico(icon):''}${cls.includes('icon')?'':esc(label)}</button>`; const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`; const $=s=>document.querySelector(s);
let db,items=[],collections=[],settings={theme:'system',layout:'masonry',cols:0,custom:{},hidden:{},norepeat:true},page='gallery',quick='all',query='',filter={},groupOps={},outer='and',activeCollection=null,limit=80,selected=new Set(),selecting=false,drawHistory=[],drawPos=-1,drawBatch=[],drawCount=1,drawMode='all',viewer=null,sheet=null,urls=new Map(),busy=false,progress=null,toastTimer,wake=null;
const app=$('#app'); const store=(n,mode='readonly')=>db.transaction(n,mode).objectStore(n); const req=r=>new Promise((ok,no)=>{r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)}); const get=(n,k)=>req(store(n).get(k)); const all=n=>req(store(n).getAll()); const rawPut=(n,v)=>new Promise((ok,no)=>{const t=db.transaction(n,'readwrite');t.objectStore(n).put(v);t.oncomplete=ok;t.onerror=()=>no(t.error);t.onabort=()=>no(t.error)}); async function put(n,v,remote=false){if(!remote&&typeof PF_LONG!=='undefined'&&ltDevice&&(n==='items'||n==='collections')){let old=await get(n,v.id);if(n==='items')PF_LONG.stamp(v,old,ltDevice);else PF_LONG.stampCollection(v,old,ltDevice)}return rawPut(n,v)} async function pairPut(meta,asset,remote=false){if(!remote&&typeof PF_LONG!=='undefined'&&ltDevice)PF_LONG.stamp(meta,await get('items',meta.id),ltDevice);await new Promise((ok,no)=>{const t=db.transaction(['items','assets'],'readwrite');t.objectStore('items').put(meta);t.objectStore('assets').put(asset);t.oncomplete=ok;t.onerror=()=>no(t.error);t.onabort=()=>no(t.error)});} async function removeItem(id){await new Promise((ok,no)=>{let t=db.transaction(['items','assets'],'readwrite');t.objectStore('items').delete(id);t.objectStore('assets').delete(id);t.oncomplete=ok;t.onerror=()=>no(t.error)});items=items.filter(x=>x.id!==id);selected.delete(id);for(const c of collections){if(c.ids.includes(id)){c.ids=c.ids.filter(x=>x!==id);await put('collections',c)}}for(const k of [id+':t',id+':o']){if(urls.has(k)){URL.revokeObjectURL(urls.get(k));urls.delete(k)}}}
function toast(s){clearTimeout(toastTimer);$('#toast').textContent=s;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function saveSettings(){return put('config',{id:'settings',...settings})} function theme(){document.body.classList.toggle('light',settings.theme==='light'||settings.theme==='system'&&matchMedia('(prefers-color-scheme: light)').matches)} matchMedia('(prefers-color-scheme: light)').addEventListener?.('change',theme);
function cats(){const r={};for(const k of new Set([...Object.keys(defaults),...Object.keys(settings.custom||{})]))r[k]=[...new Set([...(defaults[k]||[]),...(settings.custom[k]||[])])].filter(x=>!(settings.hidden[k]||[]).includes(x));return r} const find=id=>typeof ltFind==='function'?ltFind(id):items.find(x=>x.id===id); const tags=x=>Object.values(x.tags||{}).flat(); const has=(x,g,t)=>Array.isArray(x?.tags?.[g])&&x.tags[g].includes(t); const liked=x=>has(x,'收藏状态','特别收藏');
function match(x,f=filter,ops=groupOps,join=outer){let tests=[];for(const [g,dict] of Object.entries(f)){let pos=Object.keys(dict).filter(t=>dict[t]===1),neg=Object.keys(dict).filter(t=>dict[t]===-1);if(neg.some(t=>has(x,g,t)))return false;if(pos.length)tests.push(ops[g]==='and'?pos.every(t=>has(x,g,t)):pos.some(t=>has(x,g,t)));}return !tests.length||(join==='or'?tests.some(Boolean):tests.every(Boolean))}
function matches(){const words=query.trim().toLowerCase().split(/\s+/).filter(Boolean).map(w=>settings.aliases?.[w]||w);return items.filter(x=>!x.deleted&&(quick!=='liked'||liked(x))&&(quick!=='untagged'||has(x,'收藏状态','待分类'))&&(!activeCollection||collectionMatch(x,activeCollection))&&match(x)&&words.every(w=>[x.name,x.note||'',...tags(x)].join(' ').toLowerCase().includes(w))).sort((a,b)=>b.added-a.added)}
function collectionMatch(x,id){let c=collections.find(c=>c.id===id);return c&&!c.deleted&&(c.smart?match(x,c.filter,c.ops,c.outer):c.ids.includes(x.id))} function filtCount(){return Object.values(filter).reduce((n,g)=>n+Object.keys(g).length,0)}
function filterChips(){return Object.entries(filter).flatMap(([g,d])=>Object.entries(d).map(([t,v])=>`<button class="chip ${v===-1?'ex':'on'}" data-act="clearTag:${q(g)}:${q(t)}">${v===-1?'排除 ':''}${esc(t)} ×</button>`)).join('')}
const navs=[['gallery','images','图库'],['inspire','search','灵感'],['draw','shuffle','抽取'],['collections','bookmark','收藏']];function nav(){return navs.map(([p,i,t])=>btn(t,'nav:'+p,i,page===p?'active':'')).join('')}function pfPageHeader(title,sub=''){return `<header class="top"><div>${sub?`<div class="eyebrow">${sub}</div>`:''}<h1>${esc(title)}</h1></div><div class="actions">${btn('导入图片','import','plus','primary')}${btn('设置','settings','settings','icon ghost')}</div></header>`}
function empty(title,desc,action='',label=''){return `<div class="empty"><div class="emptyicon">${ico('images')}</div><h2>${esc(title)}</h2><p class="muted">${esc(desc)}</p>${action?btn(label,action,'plus','primary'):''}</div>`}
function ncols(){return settings.cols|| (innerWidth>=1250?4:innerWidth>=760?3:2)}
function tile(x){return `<article class="tile ${settings.layout==='grid'?'grid':''} ${selected.has(x.id)?'selected':''}" style="--ratio:${Math.max(.28,Math.min(3.5,x.w/x.h||.75))}" data-act="${selecting?'select':'open'}:${q(x.id)}" tabindex="0" role="button" aria-label="查看 ${esc(x.name)}"><img data-asset="${esc(x.id)}" data-kind="t" alt="${esc(x.name)}" loading="lazy" ${urls.has(x.id+':t')?`src="${urls.get(x.id+':t')}"`:''}>${selecting?btn(selected.has(x.id)?'取消选择':'选择','select:'+q(x.id),selected.has(x.id)?'check':'plus','pick icon'):btn('喜欢','like:'+q(x.id),'heart','heart icon '+(liked(x)?'liked':''))}</article>`}
function galleryGrid(list){if(!list.length)return empty(items.length?'没有符合条件的参考图':'你的灵感从这里开始',items.length?'尝试清除部分筛选，或者导入更多图片。':'导入喜欢的照片、动漫或插画。所有图片统一存放在这一本图库。',items.length?'clearAll':'import',items.length?'清除筛选':'导入第一张图')+(typeof ltRelaxHtml==='function'?ltRelaxHtml():'');const cols=ncols(),start=Math.min(typeof ltPage==='number'?ltPage:0,Math.floor((list.length-1)/80))*80,show=list.slice(start,start+80);let g;if(settings.layout==='grid')g=show.map(tile).join('');else{const c=Array.from({length:cols},()=>[]),heights=Array(cols).fill(0);for(const x of show){let i=heights.indexOf(Math.min(...heights));c[i].push(x);heights[i]+=x.h/x.w||1;}g=c.map(a=>`<div class="gcol">${a.map(tile).join('')}</div>`).join('')}return `<div class="gallery" style="--cols:${cols}">${g}</div>${start>0?btn('上一页','ltPage:-1','left','loadmore'):''}${start+80<list.length?btn(`下一页（${Math.min(start+80,list.length)} / ${list.length}）`,'ltPage:1','right','loadmore'):''}`}
function searchBar(){return `<div class="search">${ico('search')}<input id="query" placeholder="搜索姿势、感觉、角色…" value="${esc(query)}" aria-label="搜索标签与备注">${btn('筛选','filter','filter','icon')}</div>`}
function gallery(){const list=matches();return pfPageHeader(activeCollection?collections.find(c=>c.id===activeCollection)?.name||'合集':'拾姿.','POSEFRAME / 灵感图库')+searchBar()+` ${items.length>=100&&(!settings.lastBackup||Date.now()-settings.lastBackup>30*86400000)?'<div class="pillnote">建议定期备份图库 · 设置 → 完整分卷备份</div>':''}<div class="strip">${[['all','全部'],['liked','喜欢'],['untagged','待分类']].map(([k,t])=>btn(t,'quick:'+k,'','chip '+(quick===k?'on':''))).join('')}${btn('站姿','fast:'+q('姿势')+':'+q('站姿'),'','chip')}${btn('御姐感','fast:'+q('角色感觉')+':'+q('御姐感'),'','chip')}</div><div class="chips">${filterChips()}${activeCollection?btn('退出合集','clearCollection','','chip')+btn('删除合集','deleteCollection','trash','chip danger'):''}</div>${progress?`<div class="notice">${ico('spark')}<div class="grow"><b>正在导入和读取图片属性</b><div class="progress"><i style="width:${progress.done/progress.total*100}%"></i></div><small>${progress.done}/${progress.total}</small></div></div>`:''}<div class="sectionhead"><small>${list.length} 张灵感${filtCount()?' · 已筛选':''}</small><div class="actions">${btn(selecting?'完成':'选择','selectMode','','small ghost')}${btn('布局','layout','grid','icon ghost')}${btn('抽取此范围','drawFrom','shuffle','icon ghost')}</div></div>${selecting?`<div class="batchbar row wrap"><b>${selected.size} 张</b>${btn('全选','selectAll','','small')}${btn('加标签','batchTags','tags','small')}${btn('移除标签','ltBatchRemove','tags','small')}${btn('对比','ltCompare','images','small')}${btn('加入合集','addCollection','bookmark','small')}${btn('删除','batchDelete','trash','small danger')}</div>`:''}${galleryGrid(list)}`}
function cover(g,t){let x=items.find(x=>!x.deleted&&has(x,g,t));return x?`<img data-asset="${esc(x.id)}" data-kind="t" alt="">`:''}
function inspire(){let feelings=['御姐感','少女感','少年感','萌系感','神性感','反派感'];return pfPageHeader('找灵感','DISCOVER')+searchBar()+`<div class="sectionhead"><h2>想要什么感觉？</h2><small>来自你的图库</small></div><div class="category-grid">${feelings.map(t=>`<button class="category" data-act="fast:${q('角色感觉')}:${q(t)}">${cover('角色感觉',t)}<span>${esc(t)}</span><small>${items.filter(x=>has(x,'角色感觉',t)).length} 张</small></button>`).join('')}</div><div class="sectionhead"><h2>常用分类</h2>${btn('全部筛选','filter','filter','small ghost')}</div><div class="chips">${Object.keys(cats()).map(g=>btn(g,'filterGroup:'+q(g),'','chip')).join('')}</div><div class="panel"><h3>自由组合</h3><p class="muted">同组默认「或」，不同组默认「且」，也可以排除标签或调整组内逻辑。</p>${btn('打开筛选','filter','filter','primary')}</div>`}
function drawPool(){return matches().filter(x=>!has(x,'收藏状态','不再使用')&&(drawMode!=='liked'||liked(x))&&(drawMode!=='untried'||!has(x,'收藏状态','已拍摄')))}
function draw(){let x=find(drawHistory[drawPos]),pool=drawPool();return pfPageHeader('抽个灵感','SHUFFLE')+`<div class="drawlayout"><div><div class="drawstage" id="drawstage">${drawBatch.length>1?`<div class="drawbatch">${drawBatch.map(id=>`<button data-act="open:${q(id)}"><img data-asset="${esc(id)}" data-kind="t" alt="参考图"></button>`).join('')}</div>`:x?`<img data-asset="${esc(x.id)}" data-kind="o" data-act="open:${q(x.id)}" alt="${esc(x.name)}">`:empty('下一张，拍什么？','从当前筛选范围随机选择一张参考图。')}</div><div class="drawcontrols">${btn('上一张','drawPrev','left',drawPos<=0?'':'')}${btn('换一张','drawNext','shuffle','primary')}${btn('喜欢',x?'like:'+q(x.id):'none','heart',x&&liked(x)?'primary':'')}${btn('现场模式',x?'field:'+q(x.id):'none','camera')}</div>${x?`<div class="row wrap space"><small>本次第 ${drawPos+1} 张 · 已抽取 ${new Set(drawHistory).size} 张</small>${btn('拍完了','shot:'+q(x.id),'check','small')}</div>`:''}</div><aside class="panel sidepanel"><h2>抽取条件</h2><div class="sectionhead"><small>候选 ${pool.length} 张</small>${btn('筛选','filter','filter','small')}</div><div class="chips">${filterChips()||'<small>全部参考图</small>'}</div><div class="field"><label for="drawMode">抽取范围</label><select id="drawMode"><option value="all">当前范围</option><option value="liked" ${drawMode==='liked'?'selected':''}>特别收藏</option><option value="untried" ${drawMode==='untried'?'selected':''}>未拍摄</option></select></div><div class="field"><label for="drawCount">每次抽取</label><select id="drawCount">${[1,3,6,9].map(n=>`<option value="${n}" ${n===drawCount?'selected':''}>${n} 张</option>`).join('')}</select></div><div class="field"><label>抽取方式</label><select id="ltDrawStyle">${[['random','完全随机'],['diverse','多样性'],['set','组合景别']].map(([v,l])=>`<option value="${v}" ${settings.drawStyle===v?'selected':''}>${l}</option>`).join('')}</select></div><label class="switchrow">本次不重复<input type="checkbox" id="norepeat" ${settings.norepeat?'checked':''}></label>${btn('重新开始本次抽取','drawReset','','small ghost')}</aside></div>`}
function collectionPage(){return pfPageHeader('收藏','COLLECTIONS')+`<div class="category-grid"><button class="category collection" data-act="quick:liked">${cover('收藏状态','特别收藏')}<span>特别收藏 ♡</span><small>${items.filter(x=>!x.deleted&&liked(x)).length} 张</small></button>${collections.filter(c=>!c.deleted).map(c=>{let x=items.find(x=>!x.deleted&&collectionMatch(x,c.id));return `<button class="category collection" data-act="collection:${q(c.id)}">${x?`<img data-asset="${esc(x.id)}" data-kind="t" alt="">`:''}<span>${esc(c.name)}</span><small>${c.smart?'智能合集 · ':''}${items.filter(x=>!x.deleted&&collectionMatch(x,c.id)).length} 张</small></button>`}).join('')}</div><div class="row wrap" style="margin-top:16px">${btn('新建合集','newCollection','plus','primary')}${btn('保存当前筛选为智能合集','smartCollection','bookmark')}</div>${activeCollection?btn('删除当前合集','deleteCollection','trash','danger'):''}`}
