async function assetUrl(id,kind){let k=id+':'+kind;if(urls.has(k))return urls.get(k);let a=await get('assets',id);if(!a)return '';if(kind==='t'&&!a.thumb&&a.original&&!busy){try{a.thumb=(await decodeImage(a.original)).thumb;await put('assets',a)}catch{}}let b=kind==='t'?a.thumb||a.original:a.original;if(!b)return '';if(urls.has(k))return urls.get(k);let u=URL.createObjectURL(b);urls.set(k,u);return u}
let imageObserver;function loadImages(){imageObserver?.disconnect();const load=el=>{if(el.getAttribute('src'))return;assetUrl(el.dataset.asset,el.dataset.kind||'t').then(u=>{if(el.isConnected&&u)el.src=u}).catch(()=>{});};if('IntersectionObserver'in globalThis)imageObserver=new IntersectionObserver(es=>{for(const e of es)if(e.isIntersecting){load(e.target);imageObserver.unobserve(e.target)}},{rootMargin:'250px'});for(const el of document.querySelectorAll('img[data-asset]')){if(el.getAttribute('src'))continue;if(el.dataset.kind==='o'||!imageObserver)load(el);else imageObserver.observe(el)}const live=new Set([...document.querySelectorAll('img[data-asset]')].map(e=>e.dataset.asset+':'+(e.dataset.kind||'t')));if(urls.size>180)for(const [k,u] of urls){if(!live.has(k)){URL.revokeObjectURL(u);urls.delete(k)}if(urls.size<=120)break}}
